"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1362],{91362:a=>{a.exports=JSON.parse('{"slug":"vvod-izhs-2026-upal-na-21-procent-eskrou","locale":"ko","title":"9개월간 단독주택 준공이 21% 줄어 2021년 이후 최저를 기록했습니다","description":"2026년 일월–구월 단독주택 준공은 21% 감소한 41,4백만㎡였습니다. 에스크로와 높은 대출금리가 주택건설을 어떻게 바꾸는지 살펴봅니다.","blocks":[{"id":"b001","kind":"paragraph","text":"러시아의 2026년 9개월 주택 준공은 66,3백만㎡로 전년보다 13,4% 적었습니다. 감소는 모두 단독주택에서 발생해 21% 줄어든 41,4백만㎡였습니다. 이보다 적었던 마지막 때는 2021년의 35,1백만㎡입니다. 공동주택은 오히려 3% 늘어 24,9백만㎡였습니다. 전체 준공에서 단독주택 비중은 일 년간 5,9%포인트 낮아진 62,5%가 됐습니다."},{"id":"b002","kind":"paragraph","text":"건설량이 가장 많은 5개 지역 중 모스크바주와 쿠반에서 감소폭이 가장 컸습니다. 모스크바주의 9개월 준공은 6,9백만㎡로 29,5% 감소했고 크라스노다르주는 3,1백만㎡로 31,7% 감소했습니다. CIAN의 수석분석가 옐레나 보브롭스카야는 높은 대출금리와 경제 정체를 공통 원인으로 꼽습니다. 단독주택에는 에스크로 전환과 별장 간소등록 효과의 종료도 더해졌습니다. 스타크우드의 뱌체슬라프 아스타피예프는 사업예산이 일 년간 물가보다 빠른 10–15% 늘었다고 추정합니다."},{"id":"b003","kind":"paragraph","text":"고객이 돈을 은행에 맡기고 완성된 양복을 입어 본 뒤에야 대금을 받는 재봉사를 떠올려 보세요. 천\xb7실\xb7보조직원 급여는 자기 돈이나 대출로 먼저 냅니다. 큰 양복점은 가능해도 작은 작업장은 어렵습니다. 에스크로가 이와 같습니다. 2025년 삼월 1일부터 우대주택대출로 집을 짓는 시공사는 주택 등록 후 5영업일 안에만 대금을 받습니다. 현재 단독주택 에스크로를 취급하는 시공사는 약 1,5천 곳입니다."},{"id":"b004","kind":"paragraph","text":"또 다른 요인은 통계입니다. 단독주택 준공은 등록을 기준으로 집계하며 오랫동안 별장 간소등록 제도가 수치를 높였습니다. 과거에 지은 집을 뒤늦게 등록했기 때문입니다. 이런 등록은 단독주택 준공의 최대 25–30%를 차지했습니다. 간소등록은 2031년까지 연장됐지만 M9 디벨롭먼트의 운영책임자 안톤 미네지얀은 효과가 거의 소진됐다고 봅니다. 감소의 일부는 건설 자체가 줄었다기보다 오래된 집의 등록이 이미 끝났음을 나타냅니다."},{"id":"b005","kind":"paragraph","text":"구월 단독주택 준공은 2026년 들어 처음으로 전년보다 4% 늘어 5,3백만㎡가 됐습니다. 같은 달 단독주택 대출 건수는 팔월보다 42% 늘어 거의 17천 건이었습니다. 가정들이 시월 1일 전에 서둘렀기 때문입니다. 그날부터 자녀 한 명 가정의 우대금리가 6%에서 10–12%로 올랐습니다. 건설자금 대출이라면 준공 통계에는 나중에 반영됩니다."},{"id":"b006","kind":"paragraph","text":"건설부는 2026년 전체 주택 준공을 87,7백만㎡, 2025년보다 약 20% 감소로 예상하며 교외주택은 거의 25% 줄 것으로 봅니다. 9개월 실적보다 나쁘므로 연말에는 감소가 더 심해져야 한다는 전망입니다. 우대대출로 집을 지으려는 사람은 은행 심사를 통과한 시공사 중에서만 고를 수 있고 견적은 물가보다 빠르게 오릅니다. 대형 개발사가 작은 시공팀을 대신할 수 있지만 주택단지는 첫 분양 전에 도로와 기반시설부터 갖춰야 합니다."},{"id":"b007","kind":"heading","text":"2026년 단독주택 준공은 얼마나 줄었나요?"},{"id":"b008","kind":"paragraph","text":"2026년 일월–구월 준공은 41,4백만㎡로 전년보다 21% 적습니다. 더 적었던 해는 35,1백만㎡였던 2021년뿐입니다. 전체 주택 준공은 13% 감소한 66,3백만㎡입니다."},{"id":"b009","kind":"heading","text":"단독주택 건설에서 에스크로는 어떻게 작동하나요?"},{"id":"b010","kind":"paragraph","text":"차입자의 돈은 은행 계좌에 보관되고 시공사는 주택 등록 후 5영업일 안에 받습니다. 건설은 자기자금이나 대출로 진행합니다. 2025년 삼월 1일부터 시공사가 우대주택대출로 집을 지으면 의무 적용됩니다."},{"id":"b011","kind":"heading","text":"단독주택 준공이 회복되고 있나요?"},{"id":"b012","kind":"paragraph","text":"구월에는 2026년 들어 처음으로 전년 대비 4% 늘었습니다. 그러나 건설부는 교외주택의 연간 감소를 거의 25%로 예상하며 이는 9개월보다 더 큰 감소입니다. 시월 1일부터 자녀 한 명 가정 우대금리가 10–12%로 올라 주택 수요가 줄 수 있습니다."}],"sources":[{"label":"면적이 부족했습니다. 러시아 단독주택 준공이 21% 감소했습니다","url":"https://www.kommersant.ru/doc/9042244"},{"label":"러시아의 세 분기 주택 준공이 13,4% 줄었습니다","url":"https://1prime.ru/20261019/rosstat-874384990.html"},{"label":"구월 단독주택 준공이 2026년 처음으로 전년 수준을 웃돌았습니다","url":"https://finance.mail.ru/article/v-sentyabre-vvod-izhs-vpervyie-v-2026-m-prevyisil-uroven-proshlogo-goda-69233224/"},{"label":"러시아 주택 준공이 세 분기 동안 13% 감소했습니다","url":"https://realty.ria.ru/20261019/vvod-2125392621.html"},{"label":"186-FZ 개정: 단독주택 대출시장 참여자가 알아야 할 사항","url":"https://harant.ru/blog/bankovskie-voprosy-finansy/izmeneniya-v-186-fz-chto-vazhno-znat-uchastnikam-ipotechnogo-rynka-izhs/"}],"sourceBodySha256":"bcf9ff6044973cdce07fbb0598c5351b940a456fbe7c887a552863309c39870a"}')}}]);